-- Background base-cache snapshot for one selected version. A snapshot is one
-- plain Zip32 archive of the committed resident generated bytes plus the small
-- artifact/completion facts, written once by one worker Lua state from a cut
-- the controller already made consistent. The format is the PKWARE APPNOTE
-- subset LÖVE itself can mount: local headers, central directory, and EOCD
-- with method 0 (STORE) or 8 (raw DEFLATE), UTF-8 names, one disk, no extras,
-- no data descriptors, no encryption, no ZIP64. Reads, raw DEFLATE, and file
-- handles come from LÖVE; CRC and record assembly stay private here.
--
-- Trust: a write is verified by its own compression/write/close results and is
-- never reopened. The replacement protocol is cache.zip.new -> cache.zip with
-- cache.zip.bak holding the previous canonical archive, so a failed rotation
-- always leaves one recoverable snapshot. Bounds are checked before a record is
-- emitted; a cut beyond them is a typed persistence failure, never a truncated
-- archive.

local BinaryView = require("libs.codec.src.BinaryView")
local Errors = require("libs.errors.src.Errors")
local LuaWriter = require("libs.codec.src.LuaWriter")
local StorageErrors = require("libs.storage.src.errors")
local bit = require("bit")

local CacheArchive = {}

CacheArchive.SCHEMA = "portemon-cache-zip-v1"
CacheArchive.INDEX_MEMBER = "cache-index.lua"
CacheArchive.ARCHIVE_NAME = "cache.zip"
CacheArchive.TEMPORARY_NAME = "cache.zip.new"
CacheArchive.BACKUP_NAME = "cache.zip.bak"

-- Zip32 record bounds. Entry count reserves room for the manifest; the byte
-- limits are the archive format's own 32-bit sentinels, not tunables.
local MAX_ENTRIES = 65534
local MAX_NAME_BYTES = 0xFFFF
local MAX_RECORD_BYTES = 0xFFFFFFFF

-- Private writer pacing: an interactive snapshot never competes with
-- gameplay I/O for a sustained burst. An explicit CLI flush bypasses it.
local PACING_BYTES_PER_SECOND = 16 * 1024 * 1024
local PACING_CHUNK_BYTES = 256 * 1024

local METHOD_STORE = 0
local METHOD_DEFLATE = 8
local FLAG_UTF8 = 0x0800
local VERSION_NEEDED = 20
-- Deterministic DOS timestamp: 1980-01-01 00:00.
local DOS_TIME = 0
local DOS_DATE = 0x0021

local LOCAL_SIGNATURE = 0x04034B50
local CENTRAL_SIGNATURE = 0x02014B50
local EOCD_SIGNATURE = 0x06054B50

local ARCHIVE_CODES = {
  WRITE_FAILED = StorageErrors.CACHE_ARCHIVE_WRITE_FAILED,
  REPLACE_FAILED = StorageErrors.CACHE_ARCHIVE_REPLACE_FAILED,
  LIMIT_EXCEEDED = StorageErrors.CACHE_ARCHIVE_LIMIT_EXCEEDED,
  UNREADABLE = StorageErrors.CACHE_ARCHIVE_UNREADABLE,
  SCHEMA_INVALID = StorageErrors.CACHE_ARCHIVE_SCHEMA_INVALID,
}

-- Paths a snapshot may carry: the two generated roots only, never the retired
-- per-job receipt tree or the standalone milestone/build completion files they
-- replaced.
local GENERATED_ROOTS = { "data/generated", "assets/generated" }
local RETIRED_ROOTS = { "data/generated/jobs" }
local RETIRED_FILES = {
  ["data/generated/bootstrap.lua"] = true,
  ["data/generated/new-game-intro.lua"] = true,
  ["data/generated/field-planning.lua"] = true,
  ["data/generated/field-runtime.lua"] = true,
  ["data/generated/startup-title.lua"] = true,
  ["data/generated/startup-audio.lua"] = true,
  ["data/generated/complete.lua"] = true,
  ["data/generated/first-play.lua"] = true,
}

---@class CacheArchive.LoveHost
---@field filesystem love.filesystem
---@field data love.data
---@field timer love.timer

---@return CacheArchive.LoveHost
local function loveApi()
  local host = rawget(_G, "love")
  if host == nil then
    local ok, loaded = pcall(require, "love")
    if ok and type(loaded) == "table" then
      host = loaded
    end
  end
  assert(type(host) == "table", "the cache archive requires love")
  if host.filesystem == nil then
    pcall(require, "love.filesystem")
  end
  if host.data == nil then
    pcall(require, "love.data")
  end
  if host.timer == nil then
    pcall(require, "love.timer")
  end
  return host
end

--------------------------------------------------------------------- zip digits

---@param value integer
---@return string
local function u16(value)
  assert(value >= 0 and value <= 0xFFFF and value % 1 == 0, "zip u16 field out of range")
  return string.char(value % 256, math.floor(value / 256) % 256)
end

---@param value integer
---@return string
local function u32(value)
  assert(value >= 0 and value <= MAX_RECORD_BYTES and value % 1 == 0, "zip u32 field out of range")
  local fourth = math.floor(value / 16777216)
  assert(fourth <= 255, "zip u32 field out of range")
  return string.char(value % 256, math.floor(value / 256) % 256, math.floor(value / 65536) % 256, fourth)
end

-- LuaJIT's bit library answers signed 32-bit values; every ZIP/CRC field
-- stores the unsigned number.
---@param value integer
---@return integer
local function unsigned32(value)
  local folded = bit.band(value, 0xFFFFFFFF)
  return folded % 0x100000000
end

local CRC_TABLE

---@return integer[]
local function crcTable()
  if CRC_TABLE == nil then
    local table_ = {}
    for index = 0, 255 do
      local value = index
      for _ = 1, 8 do
        local mask = -bit.band(value, 1)
        value = bit.bxor(bit.rshift(value, 1), bit.band(0xEDB88320, mask))
      end
      table_[index] = value
    end
    CRC_TABLE = table_
  end
  return CRC_TABLE
end

-- Unsigned IEEE ZIP CRC-32 over one rooted byte view: the payload is walked
-- in place, so hashing never materializes a whole-entry string.
---@param view BinaryView
---@return integer
local function crc32View(view)
  local table_ = crcTable()
  local value = 0xFFFFFFFF
  local length = view:length()
  for offset = 0, length - 1 do
    local slot = bit.band(bit.bxor(value, view:u8(offset)), 0xFF)
    value = bit.bxor(bit.rshift(value, 8), table_[slot])
  end
  return unsigned32(bit.bnot(value))
end

---@param bytes string
---@return integer
local function crc32String(bytes)
  return crc32View(BinaryView.fromString(bytes, "zip text"))
end

---------------------------------------------------------------------- paths

---@param path string
---@return string
local function validateEntryPath(path)
  assert(type(path) == "string" and path ~= "", "snapshot member path is required")
  if path:find("\0", 1, true) or path:find("\\", 1, true) or path:sub(-1) == "/" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path is not canonical", { path = path })
  end
  if path:sub(1, 1) == "/" or path:match("^%a:") then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path must be relative", { path = path })
  end
  for component in (path .. "/"):gmatch("(.-)/") do
    if component == "" or component == "." or component == ".." then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path has an illegal component", { path = path })
    end
  end
  local underRoot = false
  for _, root in ipairs(GENERATED_ROOTS) do
    if path:sub(1, #root + 1) == root .. "/" then
      underRoot = true
    end
  end
  if not underRoot then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path is outside the generated roots", { path = path })
  end
  for _, root in ipairs(RETIRED_ROOTS) do
    if path:sub(1, #root + 1) == root .. "/" then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path names a retired receipt tree", { path = path })
    end
  end
  if RETIRED_FILES[path] then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "snapshot member path names a retired completion file", { path = path })
  end
  if #path > MAX_NAME_BYTES then
    Errors.raise(ARCHIVE_CODES.LIMIT_EXCEEDED, "snapshot member name exceeds the Zip32 field", { path = path })
  end
  return path
end

---@param versionId string
---@param fileName string
---@return string
local function archivePath(versionId, fileName)
  return versionId .. "/" .. fileName
end

-- The three physical names a version's snapshot owns, in replacement order.
---@param versionId string
---@return { canonical: string, temporary: string, backup: string }
function CacheArchive.paths(versionId)
  assert(type(versionId) == "string" and versionId ~= "", "snapshot paths require a version id")
  return {
    canonical = archivePath(versionId, CacheArchive.ARCHIVE_NAME),
    temporary = archivePath(versionId, CacheArchive.TEMPORARY_NAME),
    backup = archivePath(versionId, CacheArchive.BACKUP_NAME),
  }
end

-------------------------------------------------------------- cut preparation

---@param value unknown
---@param label string used in the failure message
---@return string[] sortedStrings
local function sortedStringList(value, label)
  assert(type(value) == "table", "snapshot cut " .. label .. " must be a list")
  local copy = {}
  for index, entry in ipairs(value) do
    assert(type(entry) == "string" and entry ~= "", "snapshot cut " .. label .. " entry is not a string")
    copy[index] = entry
  end
  table.sort(copy)
  return copy
end

---@class CacheArchive.Row
---@field path string
---@field uncompressedSize integer
---@field unsignedCrc32 integer
---@field method integer
---@field compressedSize integer
---@field offset integer

---@class CacheArchive.ArtifactRecord
---@field kind string
---@field key string
---@field marker string
---@field dependencies string[]
---@field ownedRoots string[]
---@field sharedPaths string[]
---@field files string[]

---@class CacheArchive.Cut
---@field versionId string
---@field identity table<string, unknown>
---@field sequence integer
---@field entries ResidentCache.BlobRef[] sorted by path
---@field artifacts CacheArchive.ArtifactRecord[] sorted by canonical job key
---@field milestones string[]
---@field firstPlay boolean
---@field complete boolean

-- Turn the controller's cut into the writer's ordered, validated view: sorted
-- payloads, whole-artifact coverage, and a manifest row per payload. This is
-- the only place the private record limits are decided.
---@param cut table<string, unknown>
---@return CacheArchive.Cut
local function normalizeCut(cut)
  assert(type(cut) == "table", "snapshot command must be a cut")
  local versionId = cut.versionId
  assert(type(versionId) == "string" and versionId:match("^[%w%-_]+$") ~= nil, "snapshot cut version is unsafe")
  local sequence = cut.sequence
  assert(
    type(sequence) == "number" and sequence % 1 == 0 and sequence >= 1,
    "snapshot cut sequence must be a positive integer"
  )
  assert(type(cut.identity) == "table", "snapshot cut identity is required")
  local entries = cut.entries
  assert(type(entries) == "table", "snapshot cut entries are required")
  local seen = {}
  local ordered = {}
  for index, entry in ipairs(entries) do
    assert(type(entry) == "table", "snapshot cut entry must be a record")
    local path = validateEntryPath(entry.path)
    assert(seen[path] == nil, "snapshot cut carries the same payload twice: " .. path)
    seen[path] = true
    local data = entry.data
    assert(type(data) == "userdata", "snapshot cut payload has no Data buffer: " .. path)
    ---@cast data love.Data
    assert(type(data.getSize) == "function", "snapshot cut payload has no Data buffer: " .. path)
    assert(entry.size == data:getSize(), "snapshot cut payload size contradicts its buffer: " .. path)
    ordered[index] = { path = path, data = data, size = entry.size }
  end
  table.sort(ordered, function(first, second)
    return first.path < second.path
  end)
  local indexByPath = {}
  for index, entry in ipairs(ordered) do
    indexByPath[entry.path] = index
  end

  local artifacts = cut.artifacts
  assert(type(artifacts) == "table", "snapshot cut artifacts are required")
  local coverage = {}
  local records = {}
  for position, artifact in ipairs(artifacts) do
    assert(type(artifact) == "table", "snapshot cut artifact must be a record")
    assert(type(artifact.kind) == "string" and artifact.kind ~= "", "snapshot cut artifact kind is required")
    assert(type(artifact.key) == "string" and artifact.key ~= "", "snapshot cut artifact key is required")
    assert(type(artifact.marker) == "string" and artifact.marker ~= "", "snapshot cut artifact marker is required")
    local files = sortedStringList(artifact.files, "artifact files")
    for _, path in ipairs(files) do
      assert(indexByPath[path] ~= nil, "snapshot cut artifact names an unknown payload: " .. path)
      coverage[path] = true
    end
    records[position] = {
      kind = artifact.kind,
      key = artifact.key,
      marker = artifact.marker,
      dependencies = sortedStringList(artifact.dependencies or {}, "artifact dependencies"),
      ownedRoots = sortedStringList(artifact.ownedRoots or {}, "artifact owned roots"),
      sharedPaths = sortedStringList(artifact.sharedPaths or {}, "artifact shared paths"),
      files = files,
    }
  end
  for _, entry in ipairs(ordered) do
    assert(coverage[entry.path] == true, "snapshot cut payload belongs to no artifact: " .. entry.path)
  end
  table.sort(records, function(first, second)
    return first.kind .. ":" .. first.key < second.kind .. ":" .. second.key
  end)

  if #ordered + 1 > MAX_ENTRIES then
    Errors.raise(ARCHIVE_CODES.LIMIT_EXCEEDED, "snapshot cut exceeds the Zip32 entry bound", {
      entries = #ordered,
      limit = MAX_ENTRIES - 1,
    })
  end

  return {
    versionId = versionId,
    identity = cut.identity,
    sequence = sequence,
    entries = ordered,
    artifacts = records,
    milestones = sortedStringList(cut.milestones or {}, "milestones"),
    firstPlay = cut.firstPlay == true,
    complete = cut.complete == true,
  }
end

------------------------------------------------------------ manifest encoding

-- Manifest rows are filled in while the payloads are being encoded, so the
-- index always reports the size and CRC the archive itself stored.
---@param cut CacheArchive.Cut
---@param rows CacheArchive.Row[]
---@return table<string, unknown>
local function buildIndex(cut, rows)
  local entries = {}
  local indexByPath = {}
  for position, row in ipairs(rows) do
    entries[position] = {
      path = row.path,
      uncompressedSize = row.uncompressedSize,
      unsignedCrc32 = row.unsignedCrc32,
    }
    indexByPath[row.path] = position
  end
  local artifacts = {}
  for position, record in ipairs(cut.artifacts) do
    local files = {}
    for slot, path in ipairs(record.files) do
      files[slot] = assert(indexByPath[path], "snapshot artifact file is not a manifest entry")
    end
    artifacts[position] = {
      kind = record.kind,
      key = record.key,
      marker = record.marker,
      dependencies = record.dependencies,
      ownedRoots = record.ownedRoots,
      sharedPaths = record.sharedPaths,
      files = files,
    }
  end
  return {
    schema = CacheArchive.SCHEMA,
    identity = cut.identity,
    sequence = cut.sequence,
    entries = entries,
    artifacts = artifacts,
    milestones = cut.milestones,
    firstPlay = cut.firstPlay,
    complete = cut.complete,
  }
end

--------------------------------------------------------------- writer protocol

---@class CacheArchive.Session
---@field versionId string
---@field sequence integer
---@field flush boolean
---@field stopRequested boolean

---@param code string
---@param message string
---@param context table<string, unknown>?
---@return Errors.Error
local function persistenceFailure(code, message, context)
  return Errors.new(code, message, context or {})
end

-- Poll the control channel between output chunks: a cancellation request for
-- this captured sequence stops the write before promotion, and a stop request
-- lets the current cut finish before the worker loop ends. An OS write already
-- executing is never assumed interruptible.
---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@return boolean canceled
local function pollControl(session, control)
  local canceled = false
  while true do
    local command = control:pop()
    if type(command) ~= "table" then
      break
    end
    if command.op == "cancel" and command.sequence == session.sequence then
      canceled = true
    elseif command.op == "stop" then
      session.stopRequested = true
    end
  end
  return canceled
end

-- Interactive output pacing: count the bytes just written and sleep only the
-- remainder the rate has not yet earned, so slow I/O never adds delay on top of
-- itself.
---@param flush boolean
---@return fun(bytes: integer)
local function newPacer(flush)
  local origin = loveApi().timer.getTime()
  local written = 0
  local function pace(bytes)
    written = written + bytes
    if flush then
      return
    end
    local elapsed = loveApi().timer.getTime() - origin
    local allowed = elapsed * PACING_BYTES_PER_SECOND
    if written > allowed then
      local host = loveApi()
      host.timer.sleep((written - allowed) / PACING_BYTES_PER_SECOND)
    end
  end
  return pace
end

---@class CacheArchive.Output
---@field handle love.File
---@field path string
---@field offset integer
---@field pace fun(bytes: integer)

---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@param output CacheArchive.Output
---@param bytes string|love.Data
---@return number? writtenBytes
---@return Errors.Error? failure
---@return boolean? canceled
local function writeOutput(session, control, output, bytes)
  -- Both containers are written in bounded chunks: a Data payload is read
  -- through a byte view, so pacing never copies a whole entry into one string
  -- and never writes the same buffer twice.
  local view = nil
  local length = 0
  if type(bytes) == "string" then
    length = #bytes
  else
    length = bytes:getSize()
    view = BinaryView.fromData(bytes, "snapshot output")
  end
  local position = 0
  while position < length do
    local sliceLength = math.min(PACING_CHUNK_BYTES, length - position)
    local chunk
    if view ~= nil then
      chunk = view:toString(position, sliceLength)
    else
      chunk = (bytes --[[@as string]]):sub(position + 1, position + sliceLength)
    end
    local ok, message = output.handle:write(chunk, sliceLength)
    if not ok then
      return nil,
        persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, "snapshot output write failed", {
          path = output.path,
          cause = tostring(message),
        })
    end
    position = position + sliceLength
    output.offset = output.offset + sliceLength
    output.pace(sliceLength)
    if pollControl(session, control) then
      return nil,
        persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, "snapshot write was canceled", { path = output.path }),
        true
    end
  end
  return length
end

---@param outputPath string
---@return love.File? handle
---@return string? openError
local function openOutput(outputPath)
  local fs = loveApi().filesystem
  return fs.newFile(outputPath, "w")
end

---@param path string
---@return boolean
local function exists(path)
  return loveApi().filesystem.getInfo(path) ~= nil
end

---@param path string
---@return boolean
local function removeQuietly(path)
  if not exists(path) then
    return true
  end
  local ok = loveApi().filesystem.remove(path)
  return ok == true
end

---@param source string
---@param destination string
---@return boolean, string?
local function renamePath(source, destination)
  local root = loveApi().filesystem.getSaveDirectory()
  local renamed, errorMessage = os.rename(root .. "/" .. source, root .. "/" .. destination)
  return renamed == true, errorMessage
end

---@param session CacheArchive.Session
---@param outputPath string
---@param message string
---@return Errors.Error
local function abortWrite(session, outputPath, message)
  removeQuietly(outputPath)
  return persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, message, { path = outputPath, sequence = session.sequence })
end

---@param row CacheArchive.Row
---@return string
local function localHeader(row)
  return table.concat({
    u32(LOCAL_SIGNATURE),
    u16(VERSION_NEEDED),
    u16(FLAG_UTF8),
    u16(row.method),
    u16(DOS_TIME),
    u16(DOS_DATE),
    u32(row.unsignedCrc32),
    u32(row.compressedSize),
    u32(row.uncompressedSize),
    u16(#row.path),
    u16(0),
    row.path,
  })
end

---@param row CacheArchive.Row
---@return string
local function centralRecord(row)
  return table.concat({
    u32(CENTRAL_SIGNATURE),
    u16(VERSION_NEEDED),
    u16(VERSION_NEEDED),
    u16(FLAG_UTF8),
    u16(row.method),
    u16(DOS_TIME),
    u16(DOS_DATE),
    u32(row.unsignedCrc32),
    u32(row.compressedSize),
    u32(row.uncompressedSize),
    u16(#row.path),
    u16(0),
    u16(0),
    u16(0),
    u16(0),
    u32(0),
    u32(row.offset),
    row.path,
  })
end

-- One payload entry: hash it in place, compress it once (stored when the
-- compressed form is not smaller, and always stored for PNG), then stream the
-- header and body. Only this one entry's compressed temporary exists at a time.
---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@param output CacheArchive.Output
---@param entry { path: string, data: love.Data, size: integer }
---@return CacheArchive.Row? row
---@return Errors.Error? failure
local function writeEntry(session, control, output, entry)
  local host = loveApi()
  local size = entry.size
  if size > MAX_RECORD_BYTES then
    return nil,
      persistenceFailure(ARCHIVE_CODES.LIMIT_EXCEEDED, "snapshot payload exceeds the Zip32 size field", {
        path = entry.path,
      })
  end
  local crc = crc32View(BinaryView.fromData(entry.data, entry.path))
  local body = entry.data
  local method = METHOD_STORE
  ---@type number
  local compressedSize = size
  if entry.path:sub(-4) ~= ".png" then
    local ok, compressed = pcall(host.data.compress, "data", "deflate", entry.data, 1)
    assert(ok, "host deflate compression failed: " .. tostring(compressed))
    assert(type(compressed) == "userdata", "compressed entry must be Data")
    local candidate = compressed --[[@as love.Data]]
    assert(type(candidate.getSize) == "function", "compressed entry must be Data")
    local candidateSize = candidate:getSize()
    if candidateSize < size then
      body = candidate
      method = METHOD_DEFLATE
      compressedSize = candidateSize
    end
  end
  if compressedSize > MAX_RECORD_BYTES or output.offset > MAX_RECORD_BYTES then
    return nil,
      persistenceFailure(ARCHIVE_CODES.LIMIT_EXCEEDED, "snapshot record exceeds the Zip32 offset field", {
        path = entry.path,
      })
  end
  local row = {
    path = entry.path,
    uncompressedSize = size,
    unsignedCrc32 = crc,
    method = method,
    compressedSize = compressedSize,
    offset = output.offset,
  }
  local header = localHeader(row)
  local written, failure = writeOutput(session, control, output, header)
  if written == nil then
    return nil, failure
  end
  written, failure = writeOutput(session, control, output, body)
  if written == nil then
    return nil, failure
  end
  return row
end

---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@param cut CacheArchive.Cut
---@param output CacheArchive.Output
---@return CacheArchive.Row[]? rows
---@return Errors.Error? failure
local function streamPayloads(session, control, cut, output)
  local rows = {}
  for position, entry in ipairs(cut.entries) do
    local row, failure = writeEntry(session, control, output, entry)
    if row == nil then
      return nil, failure
    end
    rows[position] = row
  end
  return rows
end

---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@param cut CacheArchive.Cut
---@param output CacheArchive.Output
---@param rows CacheArchive.Row[]
---@param manifestBytes string
---@return boolean? ok
---@return Errors.Error? failure
local function writeDirectory(session, control, cut, output, rows, manifestBytes)
  local manifestSize = #manifestBytes
  local manifestCrc = crc32String(manifestBytes)
  local manifestRow = {
    path = CacheArchive.INDEX_MEMBER,
    uncompressedSize = manifestSize,
    unsignedCrc32 = manifestCrc,
    method = METHOD_STORE,
    compressedSize = manifestSize,
    offset = output.offset,
  }
  local written, failure = writeOutput(session, control, output, localHeader(manifestRow))
  if written == nil then
    return nil, failure
  end
  written, failure = writeOutput(session, control, output, manifestBytes)
  if written == nil then
    return nil, failure
  end
  local directoryOffset = output.offset
  local all = {}
  for index, row in ipairs(rows) do
    all[index] = row
  end
  all[#all + 1] = manifestRow
  for _, row in ipairs(all) do
    written, failure = writeOutput(session, control, output, centralRecord(row))
    if written == nil then
      return nil, failure
    end
  end
  local directorySize = output.offset - directoryOffset
  if directoryOffset > MAX_RECORD_BYTES or directorySize > MAX_RECORD_BYTES then
    return nil,
      persistenceFailure(ARCHIVE_CODES.LIMIT_EXCEEDED, "snapshot directory exceeds the Zip32 fields", {
        path = cut.versionId,
      })
  end
  local count = #all
  local endRecord = table.concat({
    u32(EOCD_SIGNATURE),
    u16(0),
    u16(0),
    u16(count),
    u16(count),
    u32(directorySize),
    u32(directoryOffset),
    u16(0),
  })
  written, failure = writeOutput(session, control, output, endRecord)
  if written == nil then
    return nil, failure
  end
  return true
end

-- Replace the canonical archive with the closed temporary. Never deletes the
-- only recoverable file, and restores the backup when promotion cannot finish.
---@param paths { canonical: string, temporary: string, backup: string }
---@return nil|Errors.Error
local function rotate(paths)
  if exists(paths.canonical) then
    removeQuietly(paths.backup)
    local moved, moveError = renamePath(paths.canonical, paths.backup)
    if not moved then
      return persistenceFailure(ARCHIVE_CODES.REPLACE_FAILED, "the previous snapshot could not be moved aside", {
        path = paths.canonical,
        cause = tostring(moveError),
      })
    end
  end
  local promoted, promoteError = renamePath(paths.temporary, paths.canonical)
  if not promoted then
    if exists(paths.backup) and not exists(paths.canonical) then
      renamePath(paths.backup, paths.canonical)
    end
    return persistenceFailure(ARCHIVE_CODES.REPLACE_FAILED, "the finished snapshot could not be promoted", {
      path = paths.canonical,
      cause = tostring(promoteError),
    })
  end
  removeQuietly(paths.backup)
  return nil
end

-- One captured cut to one canonical archive. Returns nil on success or a typed
-- persistence failure; nothing visible changes on failure and no output byte is
-- ever read back.
---@param session CacheArchive.Session
---@param control table<string, function>|userdata
---@param cut CacheArchive.Cut
---@return nil|Errors.Error
local function writeSnapshot(session, control, cut)
  assert(type(cut) == "table", "snapshot writer requires its cut")
  local fs = loveApi().filesystem
  local versionDirectory = cut.versionId
  if not exists(versionDirectory) then
    local created = fs.createDirectory(versionDirectory)
    if not created then
      return persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, "the version directory could not be created", {
        path = versionDirectory,
      })
    end
  end
  local paths = CacheArchive.paths(cut.versionId)
  local handle, openError = openOutput(paths.temporary)
  if handle == nil then
    return persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, "the snapshot output could not be opened", {
      path = paths.temporary,
      cause = tostring(openError),
    })
  end
  local output = {
    handle = handle,
    path = paths.temporary,
    offset = 0,
    pace = newPacer(session.flush),
  }
  local completed, rows, failure = pcall(function()
    local writtenRows, rowFailure = streamPayloads(session, control, cut, output)
    if writtenRows == nil then
      return false, rowFailure
    end
    local manifestBytes = LuaWriter.encode(buildIndex(cut, writtenRows))
    local finished, directoryFailure = writeDirectory(session, control, cut, output, writtenRows, manifestBytes)
    if finished == nil then
      return false, directoryFailure
    end
    return true, nil
  end)
  if not completed then
    handle:close()
    return abortWrite(session, paths.temporary, "the snapshot could not be encoded: " .. tostring(rows))
  end
  if not rows then
    handle:close()
    removeQuietly(paths.temporary)
    ---@cast failure Errors.Error
    return failure
  end
  local closedOk, closeError = handle:close()
  if not closedOk then
    return abortWrite(session, paths.temporary, "the snapshot output could not be closed: " .. tostring(closeError))
  end
  if pollControl(session, control) then
    removeQuietly(paths.temporary)
    return persistenceFailure(ARCHIVE_CODES.WRITE_FAILED, "the snapshot was canceled before promotion", {
      path = paths.temporary,
    })
  end
  return rotate(paths)
end

--------------------------------------------------------------- worker entry

---@param failure unknown
---@return table<string, unknown>
local function errorRecord(failure)
  if Errors.is(failure) then
    ---@cast failure Errors.Error
    return { code = failure.code, message = failure.message, context = failure.context }
  end
  return { code = ARCHIVE_CODES.WRITE_FAILED, message = tostring(failure) }
end

local function bootstrapSource()
  return [[
local controlChannel, replyChannel, developmentPath = ...
if type(developmentPath) == "string" and developmentPath ~= "" then
  package.path = developmentPath
end
pcall(require, "love.filesystem")
pcall(require, "love.data")
pcall(require, "love.timer")
local CacheArchive = require("romdump.src.build.CacheArchive")
CacheArchive.run(controlChannel, replyChannel)
]]
end

---@return string code bootstrap for the archive writer thread entry
function CacheArchive.bootstrap()
  return bootstrapSource()
end

---@param packet table<string, unknown>
---@param cut CacheArchive.Cut
---@param failure Errors.Error? requested snapshot's persistence failure
---@return table<string, unknown>
local function acknowledgement(packet, cut, failure)
  local identity = {
    versionId = cut.versionId,
    generationId = packet.generationId,
    epoch = packet.epoch,
    sequence = cut.sequence,
  }
  if failure ~= nil then
    identity.op = "snapshot-failed"
    identity.error = errorRecord(failure)
    return identity
  end
  identity.op = "snapshot-persisted"
  return identity
end

-- Single writer loop: every command is answered with the identity of the cut it
-- tried, and the loop ends only on an explicit stop. The writer owns no
-- selection, readiness, or game policy; a failed snapshot is a persistence
-- observation for the controller to report.
---@param control table<string, function>|userdata
---@param reply table<string, function>|userdata
function CacheArchive.run(control, reply)
  assert(type(control) == "userdata" or type(control) == "table", "archive worker requires its control channel")
  assert(type(reply) == "userdata" or type(reply) == "table", "archive worker requires its reply channel")
  local session = { versionId = nil, sequence = 0, flush = false, stopRequested = false }
  while not session.stopRequested do
    local packet = control:demand()
    if type(packet) ~= "table" then
      break
    end
    if packet.op == "stop" then
      break
    end
    if packet.op == "snapshot" then
      session.flush = packet.flush == true
      local ok, cut = pcall(normalizeCut, packet)
      if ok then
        cut = cut --[[@as CacheArchive.Cut]]
        session.sequence = cut.sequence
        local failure = writeSnapshot(session, control, cut)
        reply:push(acknowledgement(packet, cut, failure))
      else
        reply:push({
          op = "snapshot-failed",
          versionId = packet.versionId,
          generationId = packet.generationId,
          epoch = packet.epoch,
          sequence = packet.sequence,
          error = errorRecord(cut),
        })
      end
    end
  end
end

------------------------------------------------------------------- hydration

---@param index unknown
---@return table<string, unknown>
local function validateIndex(index)
  if type(index) ~= "table" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest is not a table")
  end
  ---@cast index table<string, unknown>
  local allowed = {
    schema = true,
    identity = true,
    sequence = true,
    entries = true,
    artifacts = true,
    milestones = true,
    firstPlay = true,
    complete = true,
  }
  for field in pairs(index) do
    if not allowed[field] then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest has an unexpected field", { field = field })
    end
  end
  if index.schema ~= CacheArchive.SCHEMA then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest schema is not current", {
      schema = tostring(index.schema),
    })
  end
  if type(index.identity) ~= "table" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest carries no identity")
  end
  local sequence = index.sequence
  if type(sequence) ~= "number" or sequence % 1 ~= 0 or sequence < 1 then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest sequence is not a positive integer")
  end
  if type(index.entries) ~= "table" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest carries no entry list")
  end
  assert(type(index.entries) == "table", "validated manifest entries must be a table")
  if #index.entries + 1 > MAX_ENTRIES then
    Errors.raise(ARCHIVE_CODES.LIMIT_EXCEEDED, "the snapshot manifest exceeds the Zip32 entry bound")
  end
  local seen = {}
  local previous = nil
  for position, entry in ipairs(index.entries) do
    if type(entry) ~= "table" then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest entry is not a record", { index = position })
    end
    assert(type(entry) == "table", "validated manifest entry must be a record")
    local path = validateEntryPath(entry.path)
    if seen[path] then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest lists the same path twice", { path = path })
    end
    seen[path] = true
    if previous ~= nil and path < previous then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest entries are not sorted", { path = path })
    end
    previous = path
    if type(entry.uncompressedSize) ~= "number" or entry.uncompressedSize < 0 or entry.uncompressedSize % 1 ~= 0 then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest entry size is invalid", { path = path })
    end
    local crc = entry.unsignedCrc32
    if type(crc) ~= "number" or crc < 0 or crc > MAX_RECORD_BYTES or crc % 1 ~= 0 then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest entry CRC is invalid", { path = path })
    end
  end
  if type(index.artifacts) ~= "table" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest carries no artifact list")
  end
  assert(type(index.artifacts) == "table", "validated manifest artifacts must be a table")
  local covered = {}
  for position, artifact in ipairs(index.artifacts) do
    if type(artifact) ~= "table" then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest artifact is not a record", { index = position })
    end
    assert(type(artifact) == "table", "validated manifest artifact must be a record")
    assert(type(artifact.kind) == "string" and artifact.kind ~= "", "snapshot artifact kind is required")
    assert(type(artifact.key) == "string" and artifact.key ~= "", "snapshot artifact key is required")
    assert(type(artifact.marker) == "string" and artifact.marker ~= "", "snapshot artifact marker is required")
    for _, field in ipairs({ "dependencies", "ownedRoots", "sharedPaths", "files" }) do
      if type(artifact[field]) ~= "table" then
        Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest artifact field is missing", { field = field })
      end
    end
    assert(type(artifact.files) == "table", "validated artifact files must be a table")
    for _, reference in ipairs(artifact.files) do
      if type(reference) ~= "number" or reference % 1 ~= 0 or index.entries[reference] == nil then
        Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest file index does not name an entry")
      end
      local row = index.entries[reference]
      assert(type(row) == "table", "validated manifest entry must be a record")
      covered[row.path] = true
    end
  end
  for _, entry in ipairs(index.entries) do
    assert(type(entry) == "table", "validated manifest entry must be a record")
    if not covered[entry.path] then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest entry belongs to no artifact", {
        path = entry.path,
      })
    end
  end
  if type(index.milestones) ~= "table" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest carries no milestone list")
  end
  assert(type(index.milestones) == "table", "validated manifest milestones must be a table")
  for _, name in ipairs(index.milestones) do
    if type(name) ~= "string" or name == "" then
      Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest milestone is invalid")
    end
  end
  if type(index.firstPlay) ~= "boolean" or type(index.complete) ~= "boolean" then
    Errors.raise(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest completion facts are not booleans")
  end
  return index
end

---@param first unknown
---@param second unknown
---@return boolean
local function sameIdentity(first, second)
  if type(first) ~= "table" or type(second) ~= "table" then
    return false
  end
  for field, value in pairs(first) do
    if second[field] ~= value then
      return false
    end
  end
  for field in pairs(second) do
    if first[field] == nil then
      return false
    end
  end
  return true
end

---@class CacheArchive.Hydration
---@field versionId string
---@field sequence integer
---@field identity table<string, unknown>
---@field entries { path: string, data: love.Data, size: integer }[]
---@field artifacts { kind: string, key: string, marker: string, dependencies: string[], ownedRoots: string[], sharedPaths: string[], files: string[] }[]
---@field milestones string[]
---@field firstPlay boolean
---@field complete boolean

local mountSequence = 0

-- One mount identity for one hydration. The platform identifies a mounted
-- FileData archive by the name it was mounted under and keeps serving reads
-- through that FileData, while a repeated name mounts nothing and still
-- reports success. Every Lua state (game, controller, archive writer, compiler
-- worker) loads its own copy of this module, so a counter alone repeats names
-- across states; the monotonic process clock is shared by all of them and
-- supplies the process-wide part of the identity. A live mount point is also
-- visible, which covers two states minting the same instant.
---@param fs love.filesystem
---@return string identity
local function nextMountIdentity(fs)
  while true do
    mountSequence = mountSequence + 1
    local stamp = math.floor(loveApi().timer.getTime() * 1000000)
    local identity = string.format("cache-archive-%d-%d", stamp, mountSequence)
    if fs.getInfo(identity) == nil then
      return identity
    end
  end
end

-- Mount one candidate archive in its own namespace. Both the archive name and
-- the mount point are the minted identity, so no other hydration in this
-- process can serve from, or mount over, this namespace. The mounted FileData
-- stays rooted by the caller until that namespace is released.
---@param bytes string
---@return string? namespace
---@return love.FileData? mountedArchive
---@return string? archiveName
local function mountArchive(bytes)
  local fs = loveApi().filesystem
  local namespace = nextMountIdentity(fs)
  local archiveName = namespace .. ".zip"
  local fileData = fs.newFileData(bytes, archiveName)
  if fileData == nil then
    return nil
  end
  if not fs.mount(fileData, namespace) then
    fileData:release()
    return nil
  end
  return namespace, fileData, archiveName
end

-- Read one candidate snapshot exactly once: mount the compressed archive in a
-- private namespace, validate the manifest, then hydrate every declared member
-- and confirm its checked size and CRC while consuming that buffer. Any
-- failure discards the whole candidate so no partial bytes can reach live
-- state. Without an explicit file name the recoverable archive is read: the
-- canonical snapshot when it exists, otherwise the backup a failed rotation
-- left behind. An orphan temporary is never a candidate.
---@param versionId string
---@param expectedIdentity table<string, unknown>?
---@param fileName string?
---@return CacheArchive.Hydration? hydration
---@return Errors.Error? failure
function CacheArchive.open(versionId, expectedIdentity, fileName)
  assert(type(versionId) == "string" and versionId ~= "", "snapshot hydration requires a version id")
  local fs = loveApi().filesystem
  fileName = fileName or CacheArchive.recoverableFileName(versionId)
  if fileName == nil then
    return nil,
      Errors.new(ARCHIVE_CODES.UNREADABLE, "no snapshot archive is present", {
        path = archivePath(versionId, CacheArchive.ARCHIVE_NAME),
      })
  end
  local path = archivePath(versionId, fileName)
  if not exists(path) then
    return nil, Errors.new(ARCHIVE_CODES.UNREADABLE, "no snapshot archive is present", { path = path })
  end
  ---@type string?
  local bytes, readError = fs.read(path)
  if bytes == nil then
    return nil,
      Errors.new(ARCHIVE_CODES.UNREADABLE, "the snapshot archive could not be read", {
        path = path,
        cause = tostring(readError),
      })
  end
  local namespace, mountedArchive, archiveName = mountArchive(bytes)
  bytes = nil
  if namespace == nil or mountedArchive == nil or archiveName == nil then
    return nil, Errors.new(ARCHIVE_CODES.UNREADABLE, "the snapshot archive could not be mounted", { path = path })
  end
  local mounted = mountedArchive
  local unmounted = false
  -- The platform names a mounted FileData archive by its archive name, not by
  -- the mount point, and it keeps reading through that FileData: release the
  -- namespace first and drop the backing only once the platform confirms it.
  local function unmount()
    if unmounted then
      return
    end
    unmounted = true
    assert(loveApi().filesystem.unmount(archiveName), "the snapshot archive mount could not be released")
    mounted:release()
  end

  local indexText = fs.read(namespace .. "/" .. CacheArchive.INDEX_MEMBER)
  if indexText == nil then
    unmount()
    return nil, Errors.new(ARCHIVE_CODES.UNREADABLE, "the snapshot manifest is missing", { path = path })
  end
  assert(type(indexText) == "string", "the snapshot manifest member must be readable text")
  local chunk, loadError = load(indexText, "@" .. CacheArchive.INDEX_MEMBER, "t", {})
  if chunk == nil then
    unmount()
    return nil,
      Errors.new(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest could not be parsed", {
        path = path,
        cause = tostring(loadError),
      })
  end
  local evaluated, index = pcall(chunk)
  if not evaluated then
    unmount()
    return nil,
      Errors.new(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot manifest could not be evaluated", {
        path = path,
        cause = tostring(index),
      })
  end
  local valid, validated = pcall(validateIndex, index)
  if not valid then
    unmount()
    return nil,
      Errors.is(validated) and validated or Errors.new(
        ARCHIVE_CODES.SCHEMA_INVALID,
        "the snapshot manifest is invalid",
        { path = path }
      )
  end
  index = validated
  assert(type(index) == "table", "validated manifest must be a table")
  if expectedIdentity ~= nil and not sameIdentity(index.identity, expectedIdentity) then
    unmount()
    return nil, Errors.new(ARCHIVE_CODES.SCHEMA_INVALID, "the snapshot belongs to another generation", { path = path })
  end

  local entries = {}
  for position, entry in ipairs(index.entries) do
    assert(type(entry) == "table", "validated manifest entry must be a record")
    local member = fs.read("data", namespace .. "/" .. entry.path)
    if member == nil then
      unmount()
      return nil,
        Errors.new(ARCHIVE_CODES.UNREADABLE, "a declared snapshot member is missing", {
          path = entry.path,
        })
    end
    assert(type(member) == "userdata", "a hydrated member must be Data")
    ---@cast member love.FileData
    local size = member:getSize()
    if size ~= entry.uncompressedSize then
      unmount()
      return nil,
        Errors.new(ARCHIVE_CODES.UNREADABLE, "a snapshot member contradicts its checked size", {
          path = entry.path,
          size = size,
          expected = entry.uncompressedSize,
        })
    end
    local crc = crc32View(BinaryView.fromData(member, entry.path))
    if crc ~= entry.unsignedCrc32 then
      unmount()
      return nil,
        Errors.new(ARCHIVE_CODES.UNREADABLE, "a snapshot member contradicts its checked CRC", {
          path = entry.path,
          unsignedCrc32 = crc,
          expected = entry.unsignedCrc32,
        })
    end
    entries[position] = { path = entry.path, data = member, size = size }
  end

  local artifacts = {}
  for position, artifact in ipairs(index.artifacts) do
    assert(type(artifact) == "table", "validated manifest artifact must be a record")
    local files = {}
    for slot, reference in ipairs(artifact.files) do
      local entry = assert(index.entries[reference], "validated manifest file index must name an entry")
      assert(type(entry) == "table", "validated manifest entry must be a record")
      files[slot] = entry.path
    end
    local dependencies = {}
    for slot, dependency in ipairs(artifact.dependencies) do
      assert(type(dependency) == "string", "snapshot artifact dependency must be a string")
      dependencies[slot] = dependency
    end
    local ownedRoots = {}
    for slot, root in ipairs(artifact.ownedRoots) do
      assert(type(root) == "string", "snapshot artifact owned root must be a string")
      ownedRoots[slot] = root
    end
    local sharedPaths = {}
    for slot, shared in ipairs(artifact.sharedPaths) do
      assert(type(shared) == "string", "snapshot artifact shared path must be a string")
      sharedPaths[slot] = shared
    end
    artifacts[position] = {
      kind = artifact.kind,
      key = artifact.key,
      marker = artifact.marker,
      dependencies = dependencies,
      ownedRoots = ownedRoots,
      sharedPaths = sharedPaths,
      files = files,
    }
  end

  local milestones = {}
  for position, name in ipairs(index.milestones) do
    milestones[position] = name
  end

  unmount()
  return {
    versionId = versionId,
    sequence = index.sequence,
    identity = index.identity,
    entries = entries,
    artifacts = artifacts,
    milestones = milestones,
    firstPlay = index.firstPlay,
    complete = index.complete,
  }
end

-- The recoverable snapshot name for a version: the canonical archive when it
-- exists, otherwise the backup the last failed rotation left behind. An orphan
-- temporary is never a boot candidate.
---@param versionId string
---@return string? fileName
function CacheArchive.recoverableFileName(versionId)
  local paths = CacheArchive.paths(versionId)
  if exists(paths.canonical) then
    return CacheArchive.ARCHIVE_NAME
  end
  if exists(paths.backup) then
    return CacheArchive.BACKUP_NAME
  end
  return nil
end

-- Restore the backup as the canonical archive when only the backup survived.
---@param versionId string
---@return boolean restored
function CacheArchive.restoreBackup(versionId)
  local paths = CacheArchive.paths(versionId)
  if exists(paths.canonical) or not exists(paths.backup) then
    return false
  end
  local restored, _ = renamePath(paths.backup, paths.canonical)
  return restored == true
end

-- An explicit cache clear removes exactly the snapshot's own known siblings:
-- the canonical archive, its temporary, and its backup.
---@param versionId string
---@return boolean
function CacheArchive.clear(versionId)
  local paths = CacheArchive.paths(versionId)
  local removed = true
  for _, path in ipairs({ paths.temporary, paths.backup, paths.canonical }) do
    if not removeQuietly(path) then
      removed = false
    end
  end
  return removed
end

return CacheArchive
